#include <vector>
#include <unordered_set>
using namespace std;

class Solution {
public:
    vector<int> findMissingElements(vector<int>& nums, int m) {
        unordered_set<int> present(nums.begin(), nums.end());
        vector<int> res;
        for (int x = 1; x <= m; ++x) {
            if (!present.count(x)) {
                res.push_back(x);
            }
        }
        return res;
    }
};

import java.util.*;

class Solution {
    public List<Integer> findMissingElements(int[] nums, int m) {
        Set<Integer> present = new HashSet<>();
        for (int x : nums) present.add(x);
        List<Integer> res = new ArrayList<>();
        for (int x = 1; x <= m; x++) {
            if (!present.contains(x)) {
                res.add(x);
            }
        }
        return res;
    }
}

var findMissingElements = function(nums, m) {
    const present = new Set(nums);
    const res = [];
    for (let x = 1; x <= m; x++) {
        if (!present.has(x)) {
            res.push(x);
        }
    }
    return res;
};
